const PUBLIC_SOURCE_TEXT='자료 출처와 이용 안내. 비공식 가족용 팬 프로젝트로 임영웅 또는 소속사와 제휴하지 않았어요. 제공된 AI 샘플을 이용한 합성 안내이며 실제 임영웅의 녹음이나 발언이 아니에요. 사진과 프로필, 앨범은 물고기뮤직 공식 홈페이지, 노래와 숏츠는 임영웅 공식 유튜브를 참고했어요. 사진, 음악, 영상의 권리는 원권리자에게 있어요. 가사나 음원 파일을 제공하지 않아요. 공식 일정 달력과 공식 공지, 보도 참고를 구별해 확인해 주세요. 건강정보는 공공기관과 의료기관 자료를 참고한 일반 안내로 진단이나 처방이 아니에요. 미리 준비한 공개 안내 음성만 가져와 읽으며 사용자 문구를 합성 서버로 보내지 않아요. 일기, 가사, 건강기록, 개인 일정, 할 일과 이름은 음성 서비스에 보내지 않아요. 준비된 인사와 이 기기에 저장된 안내 음성만 오프라인에서 들을 수 있어요. 새 안내 음성을 내려받을 때는 인터넷이 필요해요.';
function publicModalGuide(title){
 if(/걷기|산책/.test(title))return '함께 걷기 안내예요. 오늘 몸 상태에 맞게 천천히 걸어요. 목표 걸음 수는 의무가 아니에요. 무리하지 말고 평평하고 안전한 길을 골라요. 어지럽거나 가슴이 아프고 숨이 차면 즉시 멈추고 도움을 요청해요. 실제 걸음 수와 개인 기록은 읽지 않아요. 일반 안내이며 진단이나 실제 가수의 추천이 아니에요.';
 if(/스트레칭|몸 풀기/.test(title))return '앉아서 몸 풀기 안내예요. 바퀴 없는 튼튼한 의자를 벽 가까이에 두고 편안하게 앉아요. 발을 바닥에 놓고 천천히 호흡해요. 통증 없는 범위에서 어깨와 발목을 가볍게 움직이고 무리한 자세는 하지 않아요. 아프거나 어지러우면 즉시 멈춰요. 치료나 개인별 운동 처방이 아니며 실제 가수의 추천이 아니에요.';
 const guides={'자료 출처와 약속':PUBLIC_SOURCE_TEXT,'영웅에 대해 궁금해요':'공식 자료로 확인한 질문과 답이에요. 각 질문의 답 읽기를 누르면 공개된 답과 설명만 읽어요. 검색어는 보내지 않아요.','내가 편한 설정':'이름, 글자 크기와 화면 대비를 바꾸는 설정이에요. 개인 이름과 저장 기록은 읽지 않아요.','마음 한 줄 일기':'나만 보는 일기와 편지예요. 기록은 이 기기에만 저장되며 읽거나 외부 음성 서비스에 보내지 않아요.','나만의 일정 넣기':'일정을 적는 화면이에요. 개인 일정과 이름은 읽지 않아요.','가족용 일정 연결':'가족이 관리하는 일정 주소나 파일을 연결할 수 있어요. 개인 일정과 입력한 주소는 읽지 않아요.','다정한 동행 도우미':'준비된 다정한 문구를 고르는 팬메이드 도우미예요. 실제 임영웅님과의 대화가 아니에요. 내 이름, 대화, 할 일과 일정은 읽거나 음성 서비스로 보내지 않아요.','폰 첫 화면에 놓기':'크롬이나 사파리 같은 외부 브라우저에서 열어 홈 화면에 추가해 보세요. 첫 설치와 새 자료 저장에는 인터넷이 필요해요. 새 안내 음성을 내려받으려면 인터넷이 필요해요.','오늘의 행복 빙고':'오늘 해 본 작은 일을 눌러 표시해요. 다시 누르면 표시를 지울 수 있어요. 시간 제한은 없어요.','사진 짝맞추기':'같은 사진 두 장을 찾아 눌러요. 천천히 기억하며 즐겨 보세요.','나만의 큰 글씨 응원판':'큰 글씨로 응원을 띄우는 화면이에요. 깜빡임은 없어요.','내 보물함':'내가 찜한 노래와 사진 카드를 다시 찾아보는 보물함이에요. 개인 선택 목록은 읽지 않아요.'};
 return guides[title]||'이 창의 공개 안내만 읽어요. 버튼을 눌러 원하는 기능을 이용하고 닫기로 돌아가요. 개인 기록과 직접 입력한 내용은 읽거나 음성 서비스에 보내지 않아요.';
}
function getPublicNarration(){const text=$('#modal').open?modalNarration?.():PUBLIC_ROUTES[route];return typeof text==='string'&&text.trim()?text:'공개 안내가 없는 화면이에요. 개인 기록은 읽지 않아요.'}
function refreshVoiceStatus(){if(!voice)return;$$('[data-voice-status]').forEach(el=>{el.innerHTML=voice.statusHTML()})}
function readPublicScreen(){return speak(getPublicNarration(),{public:true})}
function toggleLoop(){if(!playerReady())return;if(loopEnabled){loopEnabled=false;clearInterval(loopTimer);$('#loop-toggle').textContent='구간 반복 켜기';toast('구간 반복을 껐어요.');return}const a=Number($('#loop-a').value),b=Number($('#loop-b').value),dur=player.getDuration?.()||activeSong.durationSeconds;if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<=a||b>dur){toast('시작보다 큰 끝 시간을 넣어주세요. 영상 길이 이내여야 해요.');return}state.practice[activeSong.videoId]={...state.practice[activeSong.videoId],a,b};save();loopEnabled=true;player.seekTo(a,true);player.playVideo();$('#loop-toggle').textContent='구간 반복 끄기';loopTimer=setInterval(()=>{if(player&&loopEnabled&&player.getCurrentTime()>=b)player.seekTo(a,true)},250)}
function lyricSync(){if(!lyricLines.length||lyricLines.some(x=>x.time===null)){toast('[00:15.00]처럼 시간표시가 있는 LRC 문장이 필요해요.');return}if(!playerReady())return;clearInterval(lyricTimer);$('#lyric-auto').dataset.on='no';$('#lyric-auto').textContent='5초마다 줄 넘기기';if($('#lyric-sync').dataset.on==='yes'){$('#lyric-sync').dataset.on='no';$('#lyric-sync').textContent='시간표시로 영상과 맞추기';return}$('#lyric-sync').dataset.on='yes';$('#lyric-sync').textContent='영상 따라가기 끄기';lyricTimer=setInterval(()=>{if(!player)return;const t=player.getCurrentTime();let idx=-1;for(let i=0;i<lyricLines.length;i++){if(lyricLines[i].time<=t)idx=i;else break}if(idx>=0&&idx!==lyricIndex){lyricIndex=idx;showLyricLine()}},200)}
async function startRecord(){if(recordingRequest||recorder?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('이 환경에서는 녹음이 어려워요. HTTPS 주소로 열어주세요.');return}const request={generation:mediaGeneration};recordingRequest=request;const startButton=$('#record-start');if(startButton)startButton.disabled=true;let stream=null;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(request.generation!==mediaGeneration||document.hidden||!$('#record-start')||!$('#modal').open){stream.getTracks().forEach(t=>t.stop());return}micStream=stream;const chunks=[],rec=new MediaRecorder(stream);recorder=rec;rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(micStream===stream)micStream=null;if(request.generation!==mediaGeneration||!$('#record-output'))return;const blob=new Blob(chunks,{type:rec.mimeType||chunks[0]?.type||'audio/webm'});if(recordingURL)URL.revokeObjectURL(recordingURL);recordingURL=URL.createObjectURL(blob);const output=$('#record-output');output.innerHTML='<audio controls src="'+recordingURL+'"></audio><a class="btn primary" href="'+recordingURL+'" download="내-노래연습-'+today()+'.'+(blob.type.includes('mp4')?'m4a':'webm')+'">내 녹음 파일 저장</a><p class="small muted">창을 닫기 전에 저장해 주세요.</p>';$('#record-start').disabled=false;$('#record-stop').disabled=true;};rec.start();$('#record-stop').disabled=false;$('#record-output').textContent='녹음 중이에요. 끝나면 ‘녹음 끝내기’를 눌러주세요.'}catch{stream?.getTracks().forEach(t=>t.stop());if(micStream===stream)micStream=null;if(request.generation===mediaGeneration){if($('#record-start'))$('#record-start').disabled=false;toast('마이크를 사용할 수 없어요. 권한을 허용했는지 확인해 주세요.')}}finally{if(recordingRequest===request)recordingRequest=null}}
let quizState=null;
function startQuiz(reviewOnly=false){const list=reviewOnly?D.quiz.filter(q=>state.mistakes.includes(q.id)||state.review[q.id]?.due<=today()):D.quiz;quizState={list:shuffle(list).slice(0,5),index:0,score:0,answered:false};if(!quizState.list.length){modal('복습할 문제',`<div class="empty">지금 복습할 문제는 없어요.<br>퀴즈를 풀면 다시 볼 문제가 여기 모여요.</div><button class="btn primary section" data-action="quiz">새 퀴즈 풀기</button>`);return}quizView()}
function quizView(){const z=quizState;if(z.index>=z.list.length){mark('game');modal('오늘도 한 걸음 더',`<div class="cheerboard">${icon('star')}<h2>${z.list.length}문제를 함께 풀었어요.</h2><p>${z.score}문제 정답! 참 잘하셨어요.</p></div><p class="notice section">헷갈린 문제는 내일 다시 볼 수 있어요. 정답 수보다 즐겁게 해본 게 더 중요해요.</p><div class="row section"><button class="btn primary" data-action="quiz">다른 문제 더 하기</button><button class="btn" data-action="review">헷갈린 문제 복습</button></div>`);return}z.answered=false;const q=z.list[z.index];modal('영웅 퀴즈',`<div class="row between"><span class="tag">${z.index+1} / ${z.list.length}문제</span></div><div class="progress"><span style="width:${z.index/z.list.length*100}%"></span></div><h3 class="quiz-question">${esc(q.question)}</h3><button class="btn" data-action="quiz-read">문제와 보기 읽기</button><div class="answers">${shuffle(q.options).map(o=>`<button class="btn answer" data-action="answer" data-value="${esc(o)}">${esc(o)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><p class="small muted section">제한 시간은 없어요.</p>`,{publicNarration:()=>q.question+' 보기. '+q.options.join('. ')+(z.answered?' 정답. '+q.answer+'. '+q.fact:'')})}
function answer(v){const z=quizState;if(!z||z.answered)return;z.answered=true;const q=z.list[z.index],correct=v===q.answer;if(correct){z.score++;state.mistakes=state.mistakes.filter(id=>id!==q.id)}else if(!state.mistakes.includes(q.id))state.mistakes.push(q.id);state.review[q.id]={due:addDays(today(),correct?3:1),correct};save();$$('.answer').forEach(b=>{b.disabled=true;if(b.dataset.value===q.answer)b.classList.add('correct');else if(b.dataset.value===v)b.classList.add('wrong')});$('#quiz-feedback').innerHTML=`<div class="feedback"><h3>${correct?'맞았어요!':'괜찮아요, 함께 기억해요.'}</h3><p style="margin-top:10px"><b>정답: ${esc(q.answer)}</b></p><p class="small">${esc(q.fact)}</p>${ext(q.source,'답의 출처')}<div class="row section"><button class="btn primary" data-action="quiz-next">${z.index===z.list.length-1?'결과 보기':'다음 문제'}</button><button class="btn" data-action="review-later" data-value="${q.id}">내일 다시 볼래요</button></div></div>`;$('#quiz-feedback').scrollIntoView({block:'nearest',behavior:'smooth'})}
let mem=null;
function memoryGame(pairs=4){stopMedia();const picked=shuffle(D.photos.filter(p=>p.kind==='photo')).slice(0,pairs);mem={cards:shuffle([...picked,...picked]).map((p,i)=>({p,index:i})),open:[],matched:new Set(),moves:0,locked:false,peek:false,timer:null};modal('사진 짝맞추기',`<div class="row between"><p class="small muted">같은 사진 두 장을 찾아요.</p><span id="memory-count" class="tag">0 / ${pairs}쌍</span></div><div class="row section"><button class="btn slim" data-action="memory" data-value="4">쉬운 4쌍</button><button class="btn slim" data-action="memory" data-value="6">조금 더 6쌍</button><button class="btn slim" data-action="memory-peek">사진 잠깐 보기</button></div><div class="memory-board section" id="memory-board"></div><p id="memory-message" role="status" class="notice section">시간 제한이 없어요. 마음 편히 찾아보세요.</p>`);cleanup=()=>clearTimeout(mem?.timer);drawMemory()}
function drawMemory(){if(!$('#memory-board')||!mem)return;$('#memory-board').innerHTML=mem.cards.map((c,i)=>{const revealed=mem.peek||mem.open.includes(i)||mem.matched.has(c.p.id);return `<button class="memory-card ${mem.matched.has(c.p.id)?'matched':''}" data-action="memory-flip" data-value="${i}" aria-label="${i+1}번 카드 ${revealed?esc(c.p.title):'뒤집기'}" ${mem.matched.has(c.p.id)?'disabled':''}>${revealed?`<img src="${c.p.src}" alt="${esc(c.p.title)}">`:`${icon('heart')}<small>${i+1}</small>`}</button>`}).join('');$('#memory-count').textContent=`${mem.matched.size} / ${mem.cards.length/2}쌍 · ${mem.moves}번 시도`}
function memoryFlip(i){if(!mem||mem.locked||mem.peek||mem.open.includes(i)||mem.matched.has(mem.cards[i].p.id))return;mem.open.push(i);drawMemory();if(mem.open.length===2){mem.moves++;const [a,b]=mem.open;if(mem.cards[a].p.id===mem.cards[b].p.id){mem.matched.add(mem.cards[a].p.id);mem.open=[];drawMemory();$('#memory-message').textContent='같은 사진을 찾았어요!';if(mem.matched.size===mem.cards.length/2){mark('game');$('#memory-message').textContent='모두 찾았어요. 정말 잘하셨어요!'}}else{mem.locked=true;$('#memory-message').textContent='사진을 잠깐 기억해 두세요.';mem.timer=setTimeout(()=>{if(!$('#memory-board'))return;mem.open=[];mem.locked=false;drawMemory();$('#memory-message').textContent='다른 두 장도 찾아볼까요?'},1600)}}}
let wordGame=null;
function startWords(){const candidates=songs().filter(s=>s.name.split(' ').length>=2);const s=candidates[Math.floor(Math.random()*candidates.length)];wordGame={song:s,words:shuffle(s.name.split(' ').map((text,i)=>({text,i}))),chosen:[]};modal('노래 제목 맞추기',`<p class="notice">낱말을 순서대로 눌러 노래 제목을 완성해요.</p><div class="word-slot" id="word-slot" aria-live="polite"></div><div class="row" id="word-pool"></div><div class="row section"><button class="btn" data-action="word-undo">한 칸 지우기</button><button class="btn" data-action="word-hint">제목 힌트</button><button class="btn" data-action="words">다른 노래</button></div><div id="word-feedback" class="section" role="status"></div>`);drawWords()}
function drawWords(){const w=wordGame;$('#word-slot').innerHTML=w.chosen.map(i=>`<span class="word">${esc(w.words[i].text)}</span>`).join('')||'<span class="muted small">아래 낱말을 하나씩 눌러주세요.</span>';$('#word-pool').innerHTML=w.words.map((o,i)=>`<button class="word" data-action="word-pick" data-value="${i}" ${w.chosen.includes(i)?'disabled':''}>${esc(o.text)}</button>`).join('');if(w.chosen.length===w.words.length){const correct=w.chosen.map(i=>w.words[i].text).join(' ')===w.song.name;$('#word-feedback').innerHTML=correct?`<div class="feedback"><b>완성했어요! ${esc(w.song.name)}</b><div class="row section"><button class="btn primary" data-action="song" data-value="${w.song.videoId}">이 노래 듣기</button><button class="btn" data-action="words">다음 노래</button></div></div>`:'<p class="notice warm">조금만 순서를 바꿔볼까요? 한 칸 지우기로 다시 해보세요.</p>';if(correct)mark('game')}else $('#word-feedback').textContent=''}
let cup=null;
function worldcup(){cup={round:shuffle(songs()).slice(0,8),next:[],index:0};cupView()}
function cupView(){if(cup.round.length===1){const win=cup.round[0];mark('game');modal('내 마음속 1등 곡',`<div class="cheerboard"><p>오늘 내가 고른 노래</p><h2 style="font-size:1.8rem">${esc(win.name)}</h2></div><div class="row section"><button class="btn primary" data-action="song" data-value="${win.videoId}">1등 노래 듣기</button><button class="btn" data-action="favsong" data-value="${win.videoId}">내 보물함에 찜</button><button class="btn" data-action="worldcup">다시 골라보기</button></div>`);return}const pair=cup.round.slice(cup.index,cup.index+2);modal('내 마음속 1등 곡',`<p class="notice">둘 중 지금 더 듣고 싶은 곡을 골라요. 정답은 없어요.</p><p class="small muted section">${cup.round.length===2?'마지막 선택':cup.round.length+'곡 중 고르기'} · ${cup.index/2+1} / ${cup.round.length/2}</p><div class="grid two worldcup section">${pair.map(s=>`<button class="song-card" style="padding:0;text-align:left" data-action="cup-pick" data-value="${s.videoId}"><img src="${esc(s.thumbnailUrl)}" style="width:100%;aspect-ratio:16/9;object-fit:cover" alt=""><div class="song-body"><h3>${esc(s.name)}</h3><span class="btn primary">이 노래가 좋아요</span></div></button>`).join('')}</div>`)}
