$('#modal').addEventListener('close',()=>{voice?.stop();modalNarration=null});
wellness=window.createHeroWellness({getState:()=>state,save,toast,modal,icon,esc,ext,today,addDays,setCleanup:fn=>{cleanup=fn},showSong,getSongs:songs,getData:()=>D});
